
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_mgga_x_js18_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_mgga_x_js18", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.207882118490785e+00, -4.124485230616322e+00, -4.007686320162863e+00, -3.846018685939881e+00, -3.625999243301500e+00, -3.333756248859475e+00, -2.958854418915877e+00, -2.501072932800920e+00, -1.978771107830458e+00, -1.430823610126269e+00, -9.294631477523950e-01, -6.562596000985009e-01, -5.562169382798275e-01, -4.742514423214980e-01, -3.470135063239247e-01, -2.189522433451674e-01, -1.185074496768456e-01, -5.395638666714393e-02, -2.012274105666205e-02, -5.340787252079180e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


